 void togglePanel(){if(expanded){expanded=false;lp.x=compactX;lp.y=compactY;}else{compactX=lp.x;compactY=lp.y;expanded=true;}draw();}
 void fitWindow(){if(view==null||destroyed)return;int width=view.getWidth(),height=view.getHeight();if(width<=0||height<=0)return;lp.x=!expanded&&dockSide>=0?(dockSide==0?0:Math.max(0,screenWidth()-width)):clampPosition(lp.x,screenWidth(),width);lp.y=clampPosition(lp.y,screenHeight(),height);try{wm.updateViewLayout(view,lp);}catch(Exception ignored){}if(!expanded){compactX=lp.x;compactY=lp.y;savePosition();}}
