 void drag(View handle){handle.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int px,py;boolean moved;public boolean onTouch(View v,android.view.MotionEvent e){int action=e.getActionMasked();if(action==android.view.MotionEvent.ACTION_DOWN){sx=e.getRawX();sy=e.getRawY();px=lp.x;py=lp.y;moved=false;return true;}if(action==android.view.MotionEvent.ACTION_MOVE){float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.abs(dx)+Math.abs(dy)>dp(7))moved=true;if(moved){lp.x=clampPosition(px+(int)dx,screenWidth(),view.getWidth());lp.y=clampPosition(py+(int)dy,screenHeight(),view.getHeight());wm.updateViewLayout(view,lp);}return true;}if(action==android.view.MotionEvent.ACTION_UP){if(!moved){togglePanel();}else{float x=e.getRawX();dockSide=x<=dp(24)?0:x>=screenWidth()-dp(24)?1:-1;compactX=lp.x;compactY=lp.y;if(dockSide>=0)expanded=false;savePosition();draw();}return true;}if(action==android.view.MotionEvent.ACTION_CANCEL){fitWindow();return true;}return true;}});}
