 void pickReplayGroup(boolean exporting){
  MainActivity.WORK.execute(()->{
   try{
    MineReplay db=MiningControl.demos(this);
    java.util.ArrayList<String> ids=new java.util.ArrayList<>(), labels=new java.util.ArrayList<>();
    if(exporting||!db.groups.isEmpty()){ids.add("");labels.add(exporting?"全部分组":"全部启用分组");}
    for(MineReplay.Group g:db.groups.values()){
     int count=db.count(g.id);
     if(!exporting&&(!g.enabled||count==0))continue;
     ids.add(g.id);labels.add(g.name+"   ·   "+count+" 步");
    }
    int selected=ids.indexOf(MiningControl.replayGroup(this));
    ui.post(()->{
     if(destroyed)return;
     if(ids.isEmpty()){Toast.makeText(this,"请先录制或导入地图",0).show();return;}
     AlertDialog dialog=new AlertDialog.Builder(this).setTitle(exporting?"导出地图":"使用哪组地图？")
      .setSingleChoiceItems(labels.toArray(new String[0]),exporting?-1:selected,(d,i)->{
       d.dismiss();String id=ids.get(i);
       if(exporting)openRouteFile(id);else work53(()->MiningControl.startReplay(this,id),"复刻："+labels.get(i));
      }).setNegativeButton("取消",null).create();
     overlayDialog53(dialog);
    });
   }catch(Exception e){ui.post(()->Toast.makeText(this,e.getMessage(),1).show());}
  });
 }
